import{assertPublicHostname,cancelResponseBody,createPublicDispatcher,fetchWithDispatcher,readBoundedResponse}from"#execution/public-destination.js";const REDIRECT_STATUSES=new Set([301,302,303,307,308]),WEB_FETCH_DESTINATION_POLICY={allowLoopback:!1};async function requestPublicUrl(e,t){let n=parseHttpsUrl(e);for(let e=0;;e++){let{dispatcher:r,response:i}=await requestOnce(n,t);try{let r=i.headers.get(`location`);if(r!==null&&REDIRECT_STATUSES.has(i.status)&&e<10){await cancelResponseBody(i),n=parseHttpsUrl(new URL(r,n).toString());continue}return await readBoundedResponse(i,t.maxResponseSize)}finally{await r.close()}}}function parseHttpsUrl(e){let t;try{t=new URL(e)}catch{throw Error(`URL must be a valid absolute https:// URL.`)}if(t.protocol!==`https:`)throw Error(`URL must start with https://`);return t}async function requestOnce(e,t){assertPublicHostname(e.hostname,WEB_FETCH_DESTINATION_POLICY);let n=await createPublicDispatcher(WEB_FETCH_DESTINATION_POLICY);try{return{dispatcher:n,response:await fetchWithDispatcher(e,{dispatcher:n,headers:t.headers,redirect:`manual`,signal:t.signal})}}catch(e){throw await n.close(),e}}export{requestPublicUrl};